import{_ as t,o,c as n,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"UC 06 — Publishing & Social (UC-107 – UC-121)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/06-publishing-social.md","filePath":"ba/use-cases/06-publishing-social.md"}'),i={name:"ba/use-cases/06-publishing-social.md"};function a(s,e,l,d,r,g){return o(),n("div",null,[...e[0]||(e[0]=[c('<h1 id="uc-06-—-publishing-social-uc-107-–-uc-121" tabindex="-1">UC 06 — Publishing &amp; Social (<code>UC-107</code> – <code>UC-121</code>) <a class="header-anchor" href="#uc-06-—-publishing-social-uc-107-–-uc-121" aria-label="Permalink to &quot;UC 06 — Publishing &amp; Social (`UC-107` – `UC-121`)&quot;">​</a></h1><p>&gt; <a href="./05-ai-features.html">&lt;&lt; 05-ai-features.md</a> | <a href="./README.html">UC Index</a> | <a href="./../07-publishing-social.html">Domain BA Spec: 07-publishing-social.md</a> | <a href="./07-subscription.html">07-subscription.md &gt;&gt;</a> &gt; &gt; Đồng bộ chuẩn xác 1-đối-1 với <code>Các FR của hệ thống - Feature_Function Requirement.csv</code> và <code>AGENTS.md</code>. Chỉ sử dụng <strong>6 Vai trò Hệ thống Chuẩn (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-use-cases-15-ucs" tabindex="-1">1. Bảng Tổng Hợp Use Cases (15 UCs) <a class="header-anchor" href="#_1-bang-tong-hop-use-cases-15-ucs" aria-label="Permalink to &quot;1. Bảng Tổng Hợp Use Cases (15 UCs)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">UC ID</th><th style="text-align:left;">Use Case Title</th><th style="text-align:left;">Canonical Actor(s)</th><th style="text-align:center;">Related FR</th><th style="text-align:left;">Business Rules</th></tr></thead><tbody><tr><td style="text-align:center;"><code>UC-107</code></td><td style="text-align:left;">Connect Social Account</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.8.1</code></td><td style="text-align:left;"><code>BR-20, BR-53</code></td></tr><tr><td style="text-align:center;"><code>UC-108</code></td><td style="text-align:left;">Disconnect Account</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.8.2</code></td><td style="text-align:left;"><code>BR-20, BR-53</code></td></tr><tr><td style="text-align:center;"><code>UC-109</code></td><td style="text-align:left;">View Dashboard Post</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.8.3</code></td><td style="text-align:left;"><code>BR-20, BR-57</code></td></tr><tr><td style="text-align:center;"><code>UC-110</code></td><td style="text-align:left;">View Posted Detail</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.8.4</code></td><td style="text-align:left;"><code>BR-20, BR-57</code></td></tr><tr><td style="text-align:center;"><code>UC-111</code></td><td style="text-align:left;">Preview Post</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.8.5</code></td><td style="text-align:left;"><code>BR-55</code></td></tr><tr><td style="text-align:center;"><code>UC-112</code></td><td style="text-align:left;">Schedule Platform Post</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.8.6</code></td><td style="text-align:left;"><code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56, BR-63</code></td></tr><tr><td style="text-align:center;"><code>UC-113</code></td><td style="text-align:left;">Track Post Status</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.8.7</code></td><td style="text-align:left;"><code>BR-20, BR-22, BR-56</code></td></tr><tr><td style="text-align:center;"><code>UC-114</code></td><td style="text-align:left;">Publish Facebook Post</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.8.8</code></td><td style="text-align:left;"><code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></td></tr><tr><td style="text-align:center;"><code>UC-115</code></td><td style="text-align:left;">Publish Facebook Story</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.8.9</code></td><td style="text-align:left;"><code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></td></tr><tr><td style="text-align:center;"><code>UC-116</code></td><td style="text-align:left;">Publish Facebook Reels</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.8.10</code></td><td style="text-align:left;"><code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></td></tr><tr><td style="text-align:center;"><code>UC-117</code></td><td style="text-align:left;">Publish Instagram Post</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.8.11</code></td><td style="text-align:left;"><code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56, BR-57</code></td></tr><tr><td style="text-align:center;"><code>UC-118</code></td><td style="text-align:left;">Publish Instagram Reels</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.8.12</code></td><td style="text-align:left;"><code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></td></tr><tr><td style="text-align:center;"><code>UC-119</code></td><td style="text-align:left;">Publish Instagram Story</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.8.13</code></td><td style="text-align:left;"><code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></td></tr><tr><td style="text-align:center;"><code>UC-120</code></td><td style="text-align:left;">Publish TikTok Video</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.8.14</code></td><td style="text-align:left;"><code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></td></tr><tr><td style="text-align:center;"><code>UC-121</code></td><td style="text-align:left;">Publish Threads Post</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.8.15</code></td><td style="text-align:left;"><code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></td></tr></tbody></table><hr><h2 id="uc-107-—-connect-social-account" tabindex="-1">UC-107 — Connect Social Account <a class="header-anchor" href="#uc-107-—-connect-social-account" aria-label="Permalink to &quot;UC-107 — Connect Social Account&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.1</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-53</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG51, MSG54</code></li><li><strong>Specification &amp; Flow:</strong> Kết nối tài khoản mạng xã hội chính thức (Facebook Page, Instagram Business, TikTok Creator/Business, Threads) vào Workspace qua OAuth 2.0 (Connect Social Account — /workspaces/:id/social-accounts). Cho phép Client hoặc quản trị viên Workspace ủy quyền đăng bài tự động; hệ thống kiểm tra giới hạn số kênh theo gói đăng ký (BR-53), mã hóa AES-256 đối với Access/Refresh Token và tự động làm mới token định kỳ (BR-53).</li></ul><hr><h2 id="uc-108-—-disconnect-account" tabindex="-1">UC-108 — Disconnect Account <a class="header-anchor" href="#uc-108-—-disconnect-account" aria-label="Permalink to &quot;UC-108 — Disconnect Account&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.2</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-53</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG51</code></li><li><strong>Specification &amp; Flow:</strong> Ngắt kết nối tài khoản mạng xã hội khỏi Workspace (Disconnect Account — /workspaces/:id/social-accounts). Hệ thống thu hồi khóa OAuth đã lưu, hủy các lịch đăng tự động đang chờ (PENDING_SCHEDULE) của kênh đó và giữ nguyên lịch sử các bài đã đăng thành công trước đây (BR-53, BR-53).</li></ul><hr><h2 id="uc-109-—-view-dashboard-post" tabindex="-1">UC-109 — View Dashboard Post <a class="header-anchor" href="#uc-109-—-view-dashboard-post" aria-label="Permalink to &quot;UC-109 — View Dashboard Post&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.3</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-57</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem bảng điều khiển tổng hợp các bài viết đã đăng thành công trên các mạng xã hội của Workspace (View Dashboard Post — /workspaces/:id/publishing/dashboard). Hiển thị danh sách bài đã xuất bản, biểu đồ phân bổ theo nền tảng (Facebook, Instagram, TikTok, Threads) và tổng hợp nhanh hiệu suất tương tác (BR-57).</li></ul><hr><h2 id="uc-110-—-view-posted-detail" tabindex="-1">UC-110 — View Posted Detail <a class="header-anchor" href="#uc-110-—-view-posted-detail" aria-label="Permalink to &quot;UC-110 — View Posted Detail&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.4</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-57</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem chi tiết nội dung và các chỉ số tương tác của một bài đăng đã xuất bản trên mạng xã hội (View Posted Detail — /workspaces/:id/publishing/posts/:postId). Hiển thị nội dung đã đăng, liên kết trực tiếp tới bài viết trên nền tảng đích (permalink), thời điểm xuất bản và các số liệu tương tác chi tiết: tổng lượt yêu thích/cảm xúc (Reactions), bình luận (Comments), chia sẻ (Shares) và lượt xem (Views) (BR-57).</li></ul><hr><h2 id="uc-111-—-preview-post" tabindex="-1">UC-111 — Preview Post <a class="header-anchor" href="#uc-111-—-preview-post" aria-label="Permalink to &quot;UC-111 — Preview Post&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.5</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-55</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG52</code></li><li><strong>Specification &amp; Flow:</strong> Xem trước giao diện hiển thị của bài đăng theo đúng bố cục đặc thù của từng mạng xã hội trước khi duyệt hoặc xuất bản (Preview Post — /workspaces/:id/tasks/:taskId/preview). Mô phỏng trực quan khung hiển thị (Desktop &amp; Mobile) của Facebook Feed/Reels/Story, Instagram Post/Reels/Story, TikTok Video và Threads Post kèm kiểm tra giới hạn ký tự và tỷ lệ khung hình (BR-55).</li></ul><hr><h2 id="uc-112-—-schedule-platform-post" tabindex="-1">UC-112 — Schedule Platform Post <a class="header-anchor" href="#uc-112-—-schedule-platform-post" aria-label="Permalink to &quot;UC-112 — Schedule Platform Post&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.6</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56, BR-63</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG36, MSG52, MSG53</code></li><li><strong>Specification &amp; Flow:</strong> Lên lịch xuất bản tự động bài viết đã được phê duyệt vào ngày giờ cụ thể trên các kênh mạng xã hội đã chọn (Schedule Platform Post — /workspaces/:id/publishing/schedule). Hệ thống kiểm tra bài viết phải đạt trạng thái APPROVED (BR-54), quy đổi thời gian hẹn giờ theo Timezone của Workspace (BR-22, phải ở tương lai tối thiểu 5 phút BR-56) và đẩy vào hàng đợi lập lịch đăng tự động.</li></ul><hr><h2 id="uc-113-—-track-post-status" tabindex="-1">UC-113 — Track Post Status <a class="header-anchor" href="#uc-113-—-track-post-status" aria-label="Permalink to &quot;UC-113 — Track Post Status&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.7</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-22, BR-56</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG07, MSG54</code></li><li><strong>Specification &amp; Flow:</strong> Theo dõi trạng thái tiến trình xuất bản bài đăng theo thời gian thực qua 4 trạng thái: PENDING, IN_PROGRESS, DONE (PUBLISHED), FAIL (Track Post Status — /workspaces/:id/publishing/queue). Hiển thị nhật ký phản hồi từ API mạng xã hội, số lần thử lại tự động (tối đa 3 lần với exponential backoff khi gặp lỗi mạng tạm thời) và cho phép nhấn Retry thủ công đối với các bài đăng bị FAIL (BR-56).</li></ul><hr><h2 id="uc-114-—-publish-facebook-post" tabindex="-1">UC-114 — Publish Facebook Post <a class="header-anchor" href="#uc-114-—-publish-facebook-post" aria-label="Permalink to &quot;UC-114 — Publish Facebook Post&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.8</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></li><li><strong>System Messages:</strong> <code>MSG07, MSG36, MSG52, MSG53, MSG54</code></li><li><strong>Specification &amp; Flow:</strong> Xuất bản trực tiếp hoặc theo lịch bài viết tiêu chuẩn (văn bản, bộ ảnh hoặc video) lên trang Facebook Page đã kết nối qua Meta Graph API (Publish Facebook Post). Kiểm tra bài viết đã được phê duyệt (BR-54), định dạng tệp hợp lệ (BR-55) và ghi nhận post_id / permalink trả về từ Facebook (BR-56, BR-55).</li></ul><hr><h2 id="uc-115-—-publish-facebook-story" tabindex="-1">UC-115 — Publish Facebook Story <a class="header-anchor" href="#uc-115-—-publish-facebook-story" aria-label="Permalink to &quot;UC-115 — Publish Facebook Story&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.9</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG36, MSG52, MSG53, MSG54</code></li><li><strong>Specification &amp; Flow:</strong> Xuất bản tin ngắn 24 giờ (Ảnh hoặc Video dọc 9:16) lên Facebook Page Story thông qua Meta Graph API (Publish Facebook Story). Kiểm tra điều kiện phê duyệt (BR-54), kích thước khung hình dọc và thời lượng video hợp lệ trước khi đẩy qua hàng đợi xuất bản (BR-55, BR-56, BR-55).</li></ul><hr><h2 id="uc-116-—-publish-facebook-reels" tabindex="-1">UC-116 — Publish Facebook Reels <a class="header-anchor" href="#uc-116-—-publish-facebook-reels" aria-label="Permalink to &quot;UC-116 — Publish Facebook Reels&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.10</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></li><li><strong>System Messages:</strong> <code>MSG07, MSG36, MSG52, MSG53, MSG54</code></li><li><strong>Specification &amp; Flow:</strong> Xuất bản video ngắn định dạng dọc (Reels) kèm mô tả và âm thanh lên Facebook Page thông qua quy trình tải lên 2 pha của Meta Reels Publishing API (Publish Facebook Reels). Kiểm tra thời lượng video (3–90 giây), tỷ lệ 9:16 (BR-55) và cập nhật trạng thái xuất bản qua RabbitMQ worker (BR-56, BR-55).</li></ul><hr><h2 id="uc-117-—-publish-instagram-post" tabindex="-1">UC-117 — Publish Instagram Post <a class="header-anchor" href="#uc-117-—-publish-instagram-post" aria-label="Permalink to &quot;UC-117 — Publish Instagram Post&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.11</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56, BR-57</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG36, MSG52, MSG53, MSG54</code></li><li><strong>Specification &amp; Flow:</strong> Xuất bản bài đăng ảnh đơn hoặc bộ ảnh xoay vòng (Carousel) kèm caption và hashtag lên tài khoản Instagram Business qua Instagram Graph API (Publish Instagram Post). Thực hiện quy trình khởi tạo Media Container và Publish Container chuẩn của Meta, kiểm tra trạng thái duyệt (BR-54) và quy chuẩn ảnh (BR-55, BR-55).</li></ul><hr><h2 id="uc-118-—-publish-instagram-reels" tabindex="-1">UC-118 — Publish Instagram Reels <a class="header-anchor" href="#uc-118-—-publish-instagram-reels" aria-label="Permalink to &quot;UC-118 — Publish Instagram Reels&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.12</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></li><li><strong>System Messages:</strong> <code>MSG07, MSG36, MSG52, MSG53, MSG54</code></li><li><strong>Specification &amp; Flow:</strong> Xuất bản video ngắn lên Instagram Reels kèm ảnh bìa (cover frame) và caption thông qua Instagram Graph API (Publish Instagram Reels). Kiểm tra định dạng MP4/MOV, tỷ lệ khung hình dọc và theo dõi tiến trình xử lý video container cho đến khi hoàn tất xuất bản (BR-55, BR-56, BR-55).</li></ul><hr><h2 id="uc-119-—-publish-instagram-story" tabindex="-1">UC-119 — Publish Instagram Story <a class="header-anchor" href="#uc-119-—-publish-instagram-story" aria-label="Permalink to &quot;UC-119 — Publish Instagram Story&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.13</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG36, MSG52, MSG53, MSG54</code></li><li><strong>Specification &amp; Flow:</strong> Xuất bản hình ảnh hoặc video ngắn 24 giờ lên Instagram Business Story qua Instagram Graph API (Publish Instagram Story). Kiểm tra bài đăng đã được duyệt (BR-54) và tuân thủ chuẩn tỷ lệ hiển thị toàn màn hình 9:16 của Instagram Story (BR-55, BR-56, BR-55).</li></ul><hr><h2 id="uc-120-—-publish-tiktok-video" tabindex="-1">UC-120 — Publish TikTok Video <a class="header-anchor" href="#uc-120-—-publish-tiktok-video" aria-label="Permalink to &quot;UC-120 — Publish TikTok Video&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.14</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG36, MSG52, MSG53, MSG54</code></li><li><strong>Specification &amp; Flow:</strong> Xuất bản video ngắn lên tài khoản TikTok thông qua TikTok Content Posting API v2 (Publish TikTok Video). Hỗ trợ cấu hình tiêu đề/caption, quyền riêng tư (Public/Friends/Private), cho phép Duet/Stitch/Comment; thực hiện truyền tải video theo từng phân đoạn (chunked upload) và ghi nhận mã bài đăng TikTok (BR-55, BR-56, BR-55).</li></ul><hr><h2 id="uc-121-—-publish-threads-post" tabindex="-1">UC-121 — Publish Threads Post <a class="header-anchor" href="#uc-121-—-publish-threads-post" aria-label="Permalink to &quot;UC-121 — Publish Threads Post&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.8.15</code> (3.8 Publishing &amp; Social)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-22, BR-34, BR-42, BR-53, BR-54, BR-55, BR-56</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG36, MSG52, MSG53, MSG54</code></li><li><strong>Specification &amp; Flow:</strong> Xuất bản bài viết văn bản (tối đa 500 ký tự) kèm hình ảnh hoặc video lên mạng xã hội Threads thông qua Threads Publishing API (Publish Threads Post). Kiểm tra giới hạn ký tự, định dạng tệp đính kèm (BR-55) và ghi nhận đường dẫn bài đăng Threads sau khi xuất bản thành công (BR-56, BR-55).</li></ul>',50)])])}const R=t(i,[["render",a]]);export{u as __pageData,R as default};
